    #[test]
    fn test_defaulteffectcommitmentfactory_interacts_with_effectcommitmentledger() {
        let factory = DefaultEffectCommitmentFactory::new();
        let config = EffectCommitmentBackendConfig::Http {
            base_url: "https://commitment.example.invalid".to_string(),
            timeout_ms: 1_000,
            max_response_body_bytes: 4_096,
            auth_token: Some("super-secret-token".to_string()),
        };

        // Debug must never render the secret.
        let rendered = format!("{config:?}");
        assert!(!rendered.contains("super-secret-token"));
        assert!(rendered.contains("<redacted>"));

        let ledger = factory.create(config);
        fn assert_port(ledger: &dyn rigorix_engine::effect_commitment::EffectCommitmentLedger) {
            let _ = ledger;
        }
        assert_port(ledger.as_ref());
    }

